using System;
using System.ComponentModel.DataAnnotations;

namespace CrownTowersClub.Models
{
    /// <summary>
    /// Represents a membership application and the applicant's details.
    /// Maps directly to the [dbo].[Members] table.
    /// </summary>
    public sealed class Member
    {
        /* ============================================================
           1. Identity
           ============================================================ */

        /// <summary>
        /// Primary Key. Auto-generated by the database (IDENTITY).
        /// </summary>
        public int MemberId { get; set; }

        [Required(ErrorMessage = "Please enter your full name.")]
        [StringLength(150)]
        public string Name { get; set; }

        [Required(ErrorMessage = "Please enter your NRIC.")]
        [RegularExpression(@"^\d{6}-\d{2}-\d{4}$", ErrorMessage = "NRIC must follow 000000-00-0000 format.")]
        [StringLength(14)]
        public string NRIC { get; set; }


        /* ============================================================
           2. Personal Details
           ============================================================ */

        [Required(ErrorMessage = "Please select your gender.")]
        [StringLength(20)]
        public string Gender { get; set; }

        [Required(ErrorMessage = "Please select your race.")]
        [StringLength(50)]
        public string Race { get; set; }

        [Required(ErrorMessage = "Please select your marital status.")]
        [StringLength(30)]
        public string MaritalStatus { get; set; }

        [Required(ErrorMessage = "Please enter your nationality.")]
        [StringLength(80)]
        public string Nationality { get; set; }

        [Required(ErrorMessage = "Please enter your date of birth.")]
        public DateTime? DateOfBirth { get; set; }

        [Required(ErrorMessage = "Please enter your place of birth.")]
        [StringLength(150)]
        public string PlaceOfBirth { get; set; }


        /* ============================================================
           3. Professional Details
           ============================================================ */

        [Required(ErrorMessage = "Please enter your company name.")]
        [StringLength(150)]
        public string CompanyName { get; set; }

        [Required(ErrorMessage = "Please enter your company address.")]
        [StringLength(500)]
        public string CompanyAddress { get; set; }

        [Required(ErrorMessage = "Please enter your department.")]
        [StringLength(100)]
        public string Department { get; set; }

        [Required(ErrorMessage = "Please enter your occupation.")]
        [StringLength(100)]
        public string Occupation { get; set; }

        [Required(ErrorMessage = "Please enter your Head of Department.")]
        [StringLength(150)]
        public string HeadOfDepartment { get; set; }

        [Required(ErrorMessage = "Please enter your floor.")]
        [StringLength(30)]
        public string Floor { get; set; }


        /* ============================================================
           4. Contact & Interests
           ============================================================ */

        [Required(ErrorMessage = "Please enter your telephone number.")]
        [StringLength(30)]
        public string Tel { get; set; }

        [Required(ErrorMessage = "Please enter your email address.")]
        [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
        [StringLength(254)]
        public string Email { get; set; }

        [Required(ErrorMessage = "Please enter your home address.")]
        [StringLength(500)]
        public string HomeAddress { get; set; }

        [Required(ErrorMessage = "Please enter your hobbies.")]
        [StringLength(500)]
        public string Hobbies { get; set; }


        /* ============================================================
           5. Declarations
           ============================================================ */

        [Range(typeof(bool), "true", "true", ErrorMessage = "You must agree to the first declaration.")]
        public bool Declaration1 { get; set; }

        [Range(typeof(bool), "true", "true", ErrorMessage = "You must agree to the second declaration.")]
        public bool Declaration2 { get; set; }


        /* ============================================================
           6. Application Status & Audit
           ============================================================ */

        public DateTime ApplicationDate { get; set; }

        [StringLength(40)]
        public string ApplicationStatus { get; set; }

        public DateTime CreatedAt { get; set; }

        public DateTime? UpdatedAt { get; set; }


        /* ============================================================
           7. Rejection & Correction
           ============================================================ */

        [StringLength(500)]
        public string RejectionReason { get; set; }

        [StringLength(150)]
        public string RejectedBy { get; set; }

        public DateTime? RejectedAt { get; set; }

        [StringLength(500)]
        public string CorrectionReason { get; set; }


        /* ============================================================
           8. Joined Membership Data (Not in dbo.Members table)
           Populated via SQL LEFT JOINs for UI display.
           ============================================================ */

        public int? MembershipId { get; set; }
        public string MembershipNumber { get; set; }
        public string MembershipStatus { get; set; }
        public string CancellationReason { get; set; }
        public string CurrentTermStatus { get; set; }
        public DateTime? AdmissionDate { get; set; }
        public int MembershipYear { get; set; } 
    }
}